      "id": 3,
      "claim": "In Scenario 2 the speaker adds hot sauce to a friend’s dinner without any mention of the friend’s consent.",
      "evidence": "The text states: “I added hot sauce to my friend's dinner.” No consent is described.",
      "weight": 0.20,
      "depends_on": []
    },
